const textoLimpio = quedan.join('\n').replace(/\n{3,}/g, '\n\n').trim();
const soloComando = textoLimpio.length < 2;

return [{ json: { esAdmin, esComandoModo, modoElegido, soloComando, textoLimpio, jid } }];

