      out.push({ cuenta: nombre + (monto !== null ? ' - $' + monto : '') + '\n\n' + bloque, idCuenta: (m && m.id) || '', monto, texto: bloque });
    }
  }
  if (!out.length){
    const todo = String(todoSiNada || '').trim();
    if (todo) out.push({ cuenta: nombre + '\n\n' + todo, idCuenta: idTodo || '', monto: null, texto: todo });
  }
  return out;
}
